# A closure built by eval(substitute(function(...) ...)) and byte-compiled by GNU R, as
# serialize() wrote it. Its byte-code constants hold the call paste0(...) with a call cell,
# not a pairlist cell, in the argument position, and the call must keep its arguments.
bytes <- ""
f <- unserialize(as.raw(strtoi(substring(bytes, seq(1, nchar(bytes), 2), seq(2, nchar(bytes), 2)), 16L)))
f("a", "b")
body(f)
